use sea_orm::prelude::*;

/// The record of who holds what: one relation per row, over a typed resource and a subject triple.
///
/// `subject_key` and `resource_id_int` are generated by the database. They are read like any other
/// column and never written — a tuple is written through the authorization writer, which owns the
/// vocabulary check and the authority check that a plain insert would skip.
#[derive(Clone, Debug, PartialEq, DeriveEntityModel, Eq)]
#[sea_orm(table_name = "relation_tuples")]
pub struct Model {
  #[sea_orm(primary_key)]
  pub id:               i64,
  pub resource_type:    String,
  pub resource_id:      String,
  pub relation:         String,
  pub subject_type:     String,
  pub subject_id:       String,
  pub subject_relation: String,
  /// `<subject_type>:<subject_id>[#<subject_relation>]`, the form every other surface speaks.
  pub subject_key:      String,
  #[sea_orm(nullable)]
  pub resource_id_int:  Option<i32>,
  #[sea_orm(nullable)]
  pub expires_at:       Option<DateTimeWithTimeZone>,
  #[sea_orm(default_value = "CURRENT_TIMESTAMP")]
  pub created_at:       DateTimeWithTimeZone,
  #[sea_orm(default_value = "'system'")]
  pub created_by:       String,
}

#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]
pub enum Relation {}

impl ActiveModelBehavior for ActiveModel {}
